input.command:
docker compose exec -T db psql -U ecommerce -d ecommerce -v ON_ERROR_STOP=0 <<'SQL'
\echo '=== INDEXES ==='
SELECT tablename, indexname FROM pg_indexes WHERE schemaname='public' ORDER BY tablename, indexname;

\echo ''
\echo '=== TRIGGER TEST (rolled back) ==='
BEGIN;
INSERT INTO members VALUES ('Test_00001','Ada','Lovelace','ada@example.com',DATE '1990-01-01',true,'12345678');
INSERT INTO items (item_name, manufacturer_name, cost, weight_kg) VALUES ('Widget','Acme',10.00,2.500),('Gadget','Acme',3.25,0.400);
INSERT INTO transactions (membership_id, transaction_ts) VALUES ('Test_00001', TIMESTAMPTZ '2026-09-01 10:00+00');

\echo '-- header right after INSERT (expect 0.00 / 0.000):'
SELECT total_items_price, total_items_weight FROM transactions;

INSERT INTO transaction_items
SELECT t.transaction_id, i.item_id, q.qty, i.cost, i.weight_kg
FROM transactions t, items i, (VALUES ('Widget',3),('Gadget',2)) AS q(nm,qty)
WHERE i.item_name = q.nm;

\echo '-- after 2 lines: 3x10.00 + 2x3.25 = 36.50 | 3x2.500 + 2x0.400 = 8.300'
SELECT total_items_price, total_items_weight FROM transactions;

UPDATE transaction_items SET quantity = 1 WHERE quantity = 3;
\echo '-- after UPDATE qty 3->1: 1x10.00 + 2x3.25 = 16.50 | 1x2.500 + 2x0.400 = 3.300'
SELECT total_items_price, total_items_weight FROM transactions;

DELETE FROM transaction_items WHERE quantity = 2;
\echo '-- after DELETE of the Gadget line: 10.00 | 2.500'
SELECT total_items_price, total_items_weight FROM transactions;

DELETE FROM transaction_items;
\echo '-- after deleting ALL lines (expect 0.00 / 0.000, not NULL):'
SELECT total_items_price, total_items_weight FROM transactions;
ROLLBACK;
SQL

