input.command:
docker compose exec -T db psql -U ecommerce -d ecommerce -v ON_ERROR_STOP=0 2>&1 <<'SQL' | grep -E 'NEGATIVE|BAD|DUP|CASCADE|RESTRICT|TRANSITION|ERROR|DETAIL|INSERT|rows\)|^ +[0-9]' | head -40
\set QUIET on
\echo '--- BAD above_18: born 2010, flagged true ---'
INSERT INTO members VALUES ('X_1','A','B','a@b.com',DATE '2010-05-05',true,'12345678');
\echo '--- BAD above_18: born 1990, flagged false ---'
INSERT INTO members VALUES ('X_2','A','B','a@b.com',DATE '1990-05-05',false,'12345678');
\echo '--- BAD mobile: 7 digits ---'
INSERT INTO members VALUES ('X_3','A','B','a@b.com',DATE '1990-05-05',true,'1234567');
\echo '--- NEGATIVE cost ---'
INSERT INTO items (item_name,manufacturer_name,cost,weight_kg) VALUES ('N','M',-1,1);
\echo '--- ZERO weight ---'
INSERT INTO items (item_name,manufacturer_name,cost,weight_kg) VALUES ('N','M',1,0);
\echo '--- DUP natural key ---'
BEGIN;
INSERT INTO items (item_name,manufacturer_name,cost,weight_kg) VALUES ('N','M',1,1);
INSERT INTO items (item_name,manufacturer_name,cost,weight_kg) VALUES ('N','M',9,9);
ROLLBACK;
\echo '--- RESTRICT: delete a member who has a transaction ---'
BEGIN;
INSERT INTO members VALUES ('Y_1','A','B','a@b.com',DATE '1990-05-05',true,'12345678');
INSERT INTO transactions (membership_id,transaction_ts) VALUES ('Y_1',now());
DELETE FROM members WHERE membership_id='Y_1';
ROLLBACK;
\echo '--- CASCADE: delete a transaction, its lines go too ---'
BEGIN;
INSERT INTO members VALUES ('Y_2','A','B','a@b.com',DATE '1990-05-05',true,'12345678');
INSERT INTO items (item_name,manufacturer_name,cost,weight_kg) VALUES ('C','M',5,1);
INSERT INTO transactions (membership_id,transaction_ts) VALUES ('Y_2',now());
INSERT INTO transaction_items SELECT t.transaction_id,i.item_id,1,5,1 FROM transactions t,items i WHERE i.item_name='C';
DELETE FROM transactions;
SELECT count(*) AS remaining_lines FROM transaction_items;
ROLLBACK;
\echo '--- TRANSITION TABLE on a multi-event trigger (my comment claims this is forbidden) ---'
CREATE TRIGGER tt_probe AFTER INSERT OR UPDATE OR DELETE ON transaction_items
  REFERENCING NEW TABLE AS n FOR EACH STATEMENT EXECUTE FUNCTION transaction_items_totals_trigger();
SQL

